{
  "project": "0327c6fd-bac8-4366-af8b-d1b992f5878a__Post-fire-effects-on-dissolved-organic-carbon-concentration_2026_Journal-of-",
  "workflow": {
    "INFRA_1": {
      "code": "INFRA",
      "category_name": "Infrastructure & Ops",
      "status": "READY",
      "prerequisites": [],
      "details": "All modeling was conducted in R using the metafor package (Viechtbauer, 2010).",
      "cyclic_routing": {}
    },
    "ACQ_1": {
      "code": "ACQ",
      "category_name": "Data Acquisition",
      "status": "READY",
      "prerequisites": [],
      "details": "We conducted a systematic search using the \u201cWeb of Science\u201d and \u201cScopus\u201d databases, between July 2022 and September 2023. We used a set of search queries designed to identify publications assessing DOC responses to wildfire in forested stream ecosystems. The queries contained the following combination patterns: (((\u201cdissolved organic carbon\u201d OR \u201cdissolved-organic-carbon\u201d OR \u201cDOC\u201d) AND (*fire* OR *burn*) AND (*forest*)) AND stream$) OR (((*fire* OR *burn*) AND (\u201cwater quality\u201d) AND dissolved AND (*forest*)) AND stream$). The search returned 258 publications (Figure S1., Supplementary Data 1)."
    },
    "INSP_1": {
      "code": "INSP",
      "category_name": "Manual Inspection",
      "status": "BLOCKED",
      "prerequisites": [
        "ACQ_1"
      ],
      "details": "All references were imported to Zotero Reference Manager where we followed PRISMA and Cochrane guidelines for inclusion\u2013exclusion criteria (Lefebvre et al., 2022; Li et al., 2023; Page et al., 2021). First, we removed duplicate entries, then we excluded all articles that did not address fire as a disturbance or did not measure DOC concentration in forested stream systems (e.g., soil, lakes, or peatland). Articles lacking numerical results on mean values, standard deviation (or errors), or sample sizes were also removed, as these data are essential for effect size calculations in meta-analysis. Likewise, we excluded studies that reported only aggregated \u201cbefore vs. after\u201d comparisons without showing values of DOC concentration per year after wildfire event (Emelko et al., 2011). We further eliminated studies featuring potential confounding anthropogenic activities (e.g., urban, mining). Only two relevant studies focused on prescribed fires (Elliott and Miniat, 2021; Olivares et al., 2019), so we decided not to include that category. A pair of independent reviewers conducted double-screening of titles, abstracts and full texts (Harrer et al., 2021; Li et al., 2023). After our screening, our meta-analysis was based on data from 14 publications."
    },
    "ACQ_2": {
      "code": "ACQ",
      "category_name": "Data Acquisition",
      "status": "BLOCKED",
      "prerequisites": [
        "INSP_1"
      ],
      "details": "Within each selected study, we extracted information on the catchment\u2019s characteristics, including climate, soil texture, the presence of permafrost, forest type, and catchment area. We also gathered data describing wildfire attributes, such as fire severity, burn extent, and the time elapsed since the fire (Fig. 1). Quantitative information, such as mean values, standard deviations (or errors), and sample sizes were recorded from the text or supplementary materials whenever possible."
    },
    "ACQ_3": {
      "code": "ACQ",
      "category_name": "Data Acquisition",
      "status": "BLOCKED",
      "prerequisites": [
        "ACQ_2"
      ],
      "details": "For instance, we used the K\u00f6ppen-Geiger updated world map (Peel et al., 2007) to confirm climate types, NASA Earth Observations Permafrost layer (Brown et al., 2002) to identify permafrost coverage, and SoilGrids 2.0 map (Poggio et al., 2021), along with the USDA Web Soil Survey (USDA Natural Resources Conservation Service, Soil Survey Staff, 2019), for soil texture information."
    },
    "ENG_1": {
      "code": "ENG",
      "category_name": "Data Engineering",
      "status": "BLOCKED",
      "prerequisites": [
        "ACQ_2"
      ],
      "details": "If these data were only available in figures, we used the \u201cWebPlotDigitizer\u201d tool (Rohatgi, 2022) to extract numerical values from published graphs. When the graphs were box and whisker plots, the mean and the standard deviation were estimated by using the online calculator published by Shi et al. (2020), and methodologies published by Luo et al. (2018) and Wan et al. (2014)."
    },
    "ENG_2": {
      "code": "ENG",
      "category_name": "Data Engineering",
      "status": "BLOCKED",
      "prerequisites": [
        "ACQ_2"
      ],
      "details": "Any references to peak flows were compiled under a common category to capture snowmelt, spring runoff, high-flow storms, and other extreme hydrological events (See Table 1)."
    },
    "ENG_3": {
      "code": "ENG",
      "category_name": "Data Engineering",
      "status": "BLOCKED",
      "prerequisites": [
        "ACQ_2"
      ],
      "details": "Quantitative information, such as mean values, standard deviations (or errors), and sample sizes were recorded from the text or supplementary materials whenever possible and tabulated for meta-analysis."
    },
    "ENG_4": {
      "code": "ENG",
      "category_name": "Data Engineering",
      "status": "BLOCKED",
      "prerequisites": [
        "ENG_1",
        "ENG_2",
        "ENG_3",
        "ACQ_3"
      ],
      "details": "Overall, the 14 publications reported on 62 unique study sites (38 burned), spanning wildfires occurring between 1947 and 2016, and contributed a total of 52 effect sizes to the meta-analysis."
    },
    "DEV_1": {
      "code": "DEV",
      "category_name": "Model Development",
      "status": "BLOCKED",
      "prerequisites": [
        "ENG_4"
      ],
      "details": "We quantify changes in DOC concentrations after wildfires, by the natural log of the response ratio (lnRR) (Hedges et al., 1999): lnRR = ln(Y1/Y2) (1); vlnRR = s1^2/(n1 Y1^2) + s2^2/(n2 Y2^2) (2); RR = exp(lnRR) (3), where Y1 and Y2 are the mean DOC concentrations, n1 and n2 are the sample sizes, and s1 and s2 are the standard deviations for the treatment and control, respectively. We back-transformed lnRR estimates using the exponential function to obtain the Response Ratio (RR) (Equation (3)), and reported the values in percentages to facilitate interpretation."
    },
    "DEV_2": {
      "code": "DEV",
      "category_name": "Model Development",
      "status": "BLOCKED",
      "prerequisites": [
        "DEV_1"
      ],
      "details": "We addressed non-independence by employing hierarchical (multilevel) models to accommodate the non-independence effect. Additionally, to represent repeated measures through time, we accounted for a model with a heteroscedastic autoregressive (HAR) structure (Viechtbauer, 2010). This approach allows variances to differ across time periods when non-independence occurs."
    },
    "DEV_3": {
      "code": "DEV",
      "category_name": "Model Development",
      "status": "BLOCKED",
      "prerequisites": [
        "DEV_2"
      ],
      "details": "We used fixed- and random-effect specifications, interpreting global heterogeneity using Cochran\u2019s Q."
    },
    "DEV_4": {
      "code": "DEV",
      "category_name": "Model Development",
      "status": "BLOCKED",
      "prerequisites": [
        "DEV_3"
      ],
      "details": "We further extended the analyses by including various \u201cmoderators\u201d, describing catchment (e.g., climate, soil texture, permafrost) and fire attributes (e.g., severity, burn extent) in mixed-effect meta-regression. This approach allowed us to evaluate whether any of the moderators could explain the variability in DOC responses."
    },
    "EXEC_1": {
      "code": "EXEC",
      "category_name": "Execution & Compute",
      "status": "BLOCKED",
      "prerequisites": [
        "INFRA_1",
        "DEV_4"
      ],
      "details": "All modeling was executed in R using the metafor package (Viechtbauer, 2010), specifically employing the \u201crma.mv\u201d function to control for potential pseudo-replication."
    },
    "EVAL_1": {
      "code": "EVAL",
      "category_name": "Evaluation & Output",
      "status": "BLOCKED",
      "prerequisites": [
        "EXEC_1"
      ],
      "details": "A multi-level model showed a mean DOC increase of 26 % (95 % CI: 15\u201338 %), peaking in the second post-fire year (23 % (95 % CI: 3 % to 47 %), and attenuation thereafter. Responses varied with catchment and fire attributes."
    },
    "EVAL_2": {
      "code": "EVAL",
      "category_name": "Evaluation & Output",
      "status": "BLOCKED",
      "prerequisites": [
        "EXEC_1"
      ],
      "details": "Results were visualized in Figs. 2\u20135 and reported in Supplementary Data 1 (Table S3, Table S4) and Supplementary Data 4. Individual study RRs are provided in Supplementary Data 1 (Table S4)."
    }
  }
}
```

