```json
{
  "project": "03adf7a9-0e90-47af-8049-a3b35635d85e__Flood-inundation-mapping-with-CYGNSS-over-CONUS--a-two-ste_2026_Journal-of-H",
  "workflow": {
    "DSGN_1": {
      "code": "DSGN",
      "category_name": "Methodological Design",
      "status": "READY",
      "prerequisites": [],
      "details": "A machine learning framework comprising two submodules using Random Forest (RF) for classification and regression; sequential two-step (STS) and parallel two-step (PTS) model structures compared with single regressor; input features grouped into five categories: CYGNSS observables, hydro-topography, hydrology, vegetation, and meteorology [Section 3.1]."
    },
    "ACQ_1": {
      "code": "ACQ",
      "category_name": "Data Acquisition",
      "status": "READY",
      "prerequisites": [],
      "details": "CYGNSS Level 1 version 2.1 data spanning from March 18, 2017 to December 31, 2019 acquired from NASA PO-DAAC; eight microsatellites tracking reflected GNSS signals over quasi-global area (38\u00b0N\u201338\u00b0S) [Ruf et al., 2016; Section 2.1]."
    },
    "ACQ_2": {
      "code": "ACQ",
      "category_name": "Data Acquisition",
      "status": "READY",
      "prerequisites": [],
      "details": "Sentinel-1 C-band SAR-based RAPID flood inundation dataset from March 2017 to December 2019, 10 m resolution binary masks generated via RAPID system (Shen et al., 2019; Yang et al., 2021) [Section 2.2]."
    },
    "ACQ_3": {
      "code": "ACQ",
      "category_name": "Data Acquisition",
      "status": "READY",
      "prerequisites": [],
      "details": "Ancillary datasets: HAND from MERIT DEM (3\u2033, \u223c 90 m) [Yamazaki et al., 2019]; global surface water occurrence and seasonality from JRC GSW (1984\u20132021, 30 m) [Pekel et al., 2016]; meteorological variables (potential evapotranspiration, 7-day and 30-day accumulated precipitation) from daily gridMET (4 km) [Abatzoglou, 2013]; vegetation indices NDVI and LAI from MODIS Terra/Aqua (MOD13A1/MYD13A1, MOD15A2/MYD15A2, 500 m); land cover type from 2019 MCD12Q1 IGBP (500 m) [Section 2.3]."
    },
    "ENG_1": {
      "code": "ENG",
      "category_name": "Data Engineering",
      "status": "BLOCKED",
      "prerequisites": [
        "ACQ_1"
      ],
      "details": "Preprocess CYGNSS records: apply five quality flags following Chew et al. (2023) and Rodriguez-Alvarez et al. (2019) including S-band powered up, large spacecraft attitude error, black-body DDM, DDM test pattern, low confidence GPS effective isotropic radiated power (ERIP) estimate; filter observations with negative antenna gains; remove incidence angles > 65\u00b0; exclude DDM peak value outside delay bins 5\u201311; remove records over regions with surface elevation > 1500 m (or > 600 m in 2017); apply ocean mask from GSW to remove ocean observations [Section 2.1]."
    },
    "ENG_2": {
      "code": "ENG",
      "category_name": "Data Engineering",
      "status": "BLOCKED",
      "prerequisites": [
