      "code": "EXEC",
      "category_name": "Execution & Compute",
      "status": "BLOCKED",
      "prerequisites": [
        "INFRA_1",
        "DEV_4"
      ],
      "details": "All modeling was executed in R using the metafor package (Viechtbauer, 2010), specifically employing the \u201crma.mv\u201d function to control for potential pseudo-replication."
    },
    "EVAL_1": {
      "code": "EVAL",
      "category_name": "Evaluation & Output",
      "status": "BLOCKED",
      "prerequisites": [
        "EXEC_1"
      ],
      "details": "A multi-level model showed a mean DOC increase of 26 % (95 % CI: 15\u201338 %), peaking in the second post-fire year (23 % (95 % CI: 3 % to 47 %), and attenuation thereafter. Responses varied with catchment and fire attributes."
    },
    "EVAL_2": {
      "code": "EVAL",
      "category_name": "Evaluation & Output",
      "status": "BLOCKED",
      "prerequisites": [
        "EXEC_1"
      ],
      "details": "Results were visualized in Figs. 2\u20135 and reported in Supplementary Data 1 (Table S3, Table S4) and Supplementary Data 4. Individual study RRs are provided in Supplementary Data 1 (Table S4)."
    }
  }
}
