{"project":"Onion Creek Flashiness Analysis","workflow":{
  "DSGN_1":{
    "code":"DSGN",
    "category_name":"Methodological Design",
    "status":"READY",
    "prerequisites":[],
    "details":"Draft a methodological design document outlining objectives: build a rainfall-runoff LSTM model for USGS station 08158000 (Onion Creek) over 2015-01-01 to 2020-12-31. Data inputs: daily precipitation and discharge. Modeling approach: use a 14-day input window of precipitation to predict daily discharge with a single-layer LSTM (50 units), train/test split 80/20. Evaluate performance with Nash–Sutcliffe Efficiency (NSE). If NSE < 0.6, apply log-transform to discharge and retrain in a QC loop."
  },
  "INFRA_1":{
    "code":"INFRA",
    "category_name":"Infrastructure",
    "status":"READY",
    "prerequisites":[],
    "details":"Install required Python libraries: pip install pandas scikit-learn tensorflow hydrostats usgs-python matplotlib"
  },
  "ACQ_1_Discharge":{
    "code":"ACQ",
    "category_name":"Data Acquisition",
    "status":"BLOCKED",
    "prerequisites":["INFRA_1"],
    "details":"Write a script named `01_acquire_discharge.py`. Use the USGS water services API via the `usgs-python` package to download daily discharge (parameter 00060) for station 08158000 from 2015-01-01 to 2020-12-31. Save the output to `data/discharge_raw.csv` with columns ['date','discharge_cfs']."
  },
  "ACQ_2_Precip":{
    "code":"ACQ",
    "category_name":"Data Acquisition",
    "status":"BLOCKED",
    "prerequisites":["INFRA_1"],
    "details":"Instruct the user to provide a daily precipitation CSV file for the Onion Creek watershed (ideally colocated with USGS 08158000) covering 2015-01-01 to 2020-12-31.",
    "ui_instructions":{
      "type":"user_upload",
      "prompt":"Please upload your local precipitation CSV file with at least ['date','precip_mm'] columns, or place it in the workspace and specify its path."
    }
  },
  "ENG_1_Align":{
    "code":"ENG",
    "category_name":"Data Engineering",
    "status":"BLOCKED",
    "prerequisites":["ACQ_1_Discharge","ACQ_2_Precip"],
    "details":"Write a script named `03_clean_merge.py`. Load `data/discharge_raw.csv` and the provided precipitation file. Parse 'date' as datetime, filter both to the period 2015-01-01 to 2020-12-31. Merge on 'date', perform linear interpolation to fill any missing values, and save the cleaned merged dataframe to `data/merged_clean.csv` with columns ['date','precip_mm','discharge_cfs']."
  },
  "INSP_1_DataCheck":{
    "code":"INSP",
    "category_name":"Manual Inspection",
    "status":"BLOCKED",
    "prerequisites":["ENG_1_Align"],
    "details":"Human reviews the cleaned and merged data summary (time coverage, missing value counts, basic statistics for precipitation and discharge).",
    "ui_instructions":{
      "type":"human_review",
      "prompt":"Review `data/merged_clean.csv` summary. Is the data complete, correctly merged, and free of obvious anomalies?"
    },
    "cyclic_routing":{
      "condition":"Did the user approve the merged dataset?",
      "if_true":["DEV_1_ModelDefinition"],
      "if_false":["ACQ_1_Discharge","ACQ_2_Precip"]
    }
  },
  "DEV_1_ModelDefinition":{
    "code":"DEV",
    "category_name":"Model Development",
    "status":"BLOCKED",
    "prerequisites":["INSP_1_DataCheck"],
    "details":"Write a script named `04_define_model.py`. Load `data/merged_clean.csv`. Split into training (first 80%) and test (last 20%) sets. Fit StandardScaler on precipitation and discharge in the training set. Define a Keras Sequential LSTM model: Input shape [14,1], one LSTM layer (50 units), dense output layer (1 unit). Compile with Adam optimizer (learning_rate=0.001) and MSE loss. Save the model architecture to `models/lstm_architecture.json` and scaler objects to `models/scalers.pkl`."
  },
  "EXEC_1_Training":{
    "code":"EXEC",
    "category_name":"Execution",
    "status":"BLOCKED",
    "prerequisites":["DEV_1_ModelDefinition"],
    "details":"Write a script named `05_train_lstm.py`. Load `models/lstm_architecture.json`, `models/scalers.pkl`, and `data/merged_clean.csv`. Prepare sliding-window sequences of 14 days of precipitation inputs and next-day discharge targets. Train the model for 50 epochs with batch_size=32. Save the full trained model to `models/lstm_model.h5` and training history to `outputs/training_history.csv`."
  },
  "EVAL_1_NSE":{
    "code":"EVAL",
    "category_name":"Evaluation",
    "status":"BLOCKED",
    "prerequisites":["EXEC_1_Training"],
    "details":"Write a script named `06_evaluate_nse.py`. Load the trained `models/lstm_model.h5`, `models/scalers.pkl`, and the test portion of `data/merged_clean.csv`. Predict discharge on test set, invert scaling, and compute Nash–Sutcliffe Efficiency (NSE) using the `hydrostats` package. Save the NSE value and a plot of observed vs. predicted discharge hydrograph to `outputs/nse_metrics.json` and `outputs/nse_plot.png`."
  },
  "INSP_2_NSECheck":{
    "code":"INSP",
    "category_name":"Manual Inspection",
    "status":"BLOCKED",
    "prerequisites":["EVAL_1_NSE"],
    "details":"Human reviews the computed NSE value.",
    "ui_instructions":{
      "type":"human_review",
      "prompt":"Review `outputs/nse_metrics.json`. Is NSE ≥ 0.6?"
    },
    "cyclic_routing":{
      "condition":"Is NSE ≥ 0.6?",
      "if_true":["DSGN_2_Report"],
      "if_false":["DEV_2_LogTransform"]
    }
  },
  "DEV_2_LogTransform":{
    "code":"DEV",
    "category_name":"Model Development",
    "status":"BLOCKED",
    "prerequisites":["INSP_2_NSECheck"],
    "details":"Write a script named `07_log_transform.py`. Load `data/merged_clean.csv`, apply natural log transform to the 'discharge_cfs' column after adding a small constant (e.g., 0.1) to avoid zeros. Resplit into training/test, refit StandardScalers, and save the log-transformed dataset to `data/merged_log.csv` and new scalers to `models/scalers_log.pkl`."
  },
  "EXEC_2_Retrain":{
    "code":"EXEC",
    "category_name":"Execution",
    "status":"BLOCKED",
    "prerequisites":["DEV_2_LogTransform"],
    "details":"Write a script named `08_train_lstm_log.py`. Load `models/lstm_architecture.json`, `models/scalers_log.pkl`, and `data/merged_log.csv`. Prepare sliding-window sequences on log-transformed targets. Retrain the model for 50 epochs, batch_size=32. Save the retrained model to `models/lstm_log_model.h5` and history to `outputs/training_history_log.csv`."
  },
  "EVAL_2_ReNSE":{
    "code":"EVAL",
    "category_name":"Evaluation",
    "status":"BLOCKED",
    "prerequisites":["EXEC_2_Retrain"],
    "details":"Write a script named `09_evaluate_nse_log.py`. Load `models/lstm_log_model.h5`, `models/scalers_log.pkl`, and test portion of `data/merged_log.csv`. Predict log-discharge, invert log transform and scaling. Compute NSE with `hydrostats`. Save updated NSE and plot to `outputs/nse_log_metrics.json` and `outputs/nse_log_plot.png`."
  },
  "INSP_3_FinalCheck":{
    "code":"INSP",
    "category_name":"Manual Inspection",
    "status":"BLOCKED",
    "prerequisites":["EVAL_2_ReNSE"],
    "details":"Human reviews the updated NSE after log-transform retraining.",
    "ui_instructions":{
      "type":"human_review",
      "prompt":"Review `outputs/nse_log_metrics.json`. Is NSE ≥ 0.6 now?"
    },
    "cyclic_routing":{
      "condition":"Is updated NSE ≥ 0.6?",
      "if_true":["DSGN_2_Report"],
      "if_false":["DEV_2_LogTransform"]
    }
  },
  "DSGN_2_Report":{
    "code":"DSGN",
    "category_name":"Methodological Design",
    "status":"BLOCKED",
    "prerequisites":["INSP_2_NSECheck","INSP_3_FinalCheck"],
    "details":"Write a summary report named `10_results_report.md`. Document data acquisition and cleaning steps, LSTM architecture, training details, final NSE performance, comparison before/after log-transform, and conclusions regarding model predictability for Onion Creek."
  }
}}

