      "details": "Create a Windows batch script `setup_env.bat` and `requirements.txt`. Install via pip: numpy, pandas, geopandas, rasterio, shapely, sentinelsat, landsatxplore, usgs-api, scikit-learn, scipy, pystarefm (or estarfm-py), matplotlib, seaborn. Ensure GDAL/PROJ available via OSGeo4W or conda-forge."
    },
    "ACQ_1_LandsatData": {
      "code": "ACQ",
      "category_name": "Data Acquisition",
      "status": "BLOCKED",
      "prerequisites": ["INFRA_1"],
      "details": "Write `01_download_landsat.py`. Define a 15×15 km bbox around USGS gauge 05454500 (approx. lat 41.6612, lon -91.5305). Use landsatxplore to authenticate, query and download Landsat 8/9 L2 products from 2023-04-01 to 2023-11-30 with cloud cover <20%. Save scenes to `data/landsat/`."
    },
    "ACQ_2_SentinelData": {
      "code": "ACQ",
      "category_name": "Data Acquisition",
      "status": "BLOCKED",
      "prerequisites": ["INFRA_1"],
      "details": "Write `02_download_sentinel.py`. Using sentinelsat, download Sentinel-2 L2A scenes over the same bbox and period with cloud cover <20%. Save to `data/sentinel/`."
    },
    "ACQ_3_Discharge": {
      "code": "ACQ",
      "category_name": "Data Acquisition",
      "status": "BLOCKED",
      "prerequisites": ["INFRA_1"],
      "details": "Write `03_download_discharge.py`. Query USGS API for daily mean discharge at gauge 05454500 from 2023-04-01 to 2023-11-30. Convert cfs to m³/s (1 cfs=0.0283168 m³/s). Save as `data/discharge.csv` with columns Date, discharge_m3s."
    },
    "ENG_1_SelectHighFlowDate": {
      "code": "ENG",
      "category_name": "Data Engineering",
      "status": "BLOCKED",
      "prerequisites": ["ACQ_3_Discharge", "ACQ_2_SentinelData"],
      "details": "Write `04_select_highflow.py`. Load `data/discharge.csv`, find date of maximum discharge. Scan `data/sentinel/` filenames or metadata for that date. Output selected sentinel filepath to `outputs/highflow_sentinel.txt` and date to `outputs/highflow_date.txt`."
    },
    "ENG_2_RiverMask": {
      "code": "ENG",
      "category_name": "Data Engineering",
      "status": "BLOCKED",
      "prerequisites": ["ENG_1_SelectHighFlowDate"],
      "details": "Write `05_create_river_mask.py`. Read selected Sentinel-2 image, compute NDWI=(Green−NIR)/(Green+NIR) using bands B3 and B8. Threshold NDWI>0.3 to binary mask. Extract main water object, buffer by 50 m, save vector to `masks/river_mask.geojson` and rasterized mask to `masks/river_mask.tif` aligned to image grid."
    },
    "INSP_1_RiverMask": {
      "code": "INSP",
      "category_name": "Manual Inspection",
      "status": "BLOCKED",
      "prerequisites": ["ENG_2_RiverMask"],
      "details": "Visualize `masks/river_mask.geojson` over the high-flow Sentinel-2 image. Confirm the buffer and mask correctly delineate the river banks.",
      "ui_instructions": {
        "type": "human_review",
        "prompt": "Overlay `masks/river_mask.geojson` on the high-flow Sentinel-2 image. Is the river mask correct?"
      },
      "cyclic_routing": {
        "condition": "Did the river mask correctly delineate the river?",
        "if_true": ["ENG_3_BasePairDates"],
        "if_false": ["ENG_2_RiverMask"]
      }
    },
    "ENG_3_BasePairDates": {
      "code": "ENG",
      "category_name": "Data Engineering",
      "status": "BLOCKED",
      "prerequisites": ["ACQ_1_LandsatData", "ACQ_2_SentinelData"],
      "details": "Write `06_identify_basepairs.py`. Scan `data/landsat/` and `data/sentinel/`, parse acquisition dates and cloud cover metadata. Identify dates where both sensors have scenes with <20% cloud. Save `basepairs.csv` with columns Date, landsat_path, sentinel_path."
    },
    "ENG_4_ResampleReproject": {
      "code": "ENG",
      "category_name": "Data Engineering",
      "status": "BLOCKED",
      "prerequisites": ["ENG_3_BasePairDates"],
      "details": "Write `07_preprocess_basepairs.py`. For each row in `basepairs.csv`, load Landsat image, resample bands to 10 m, reproject to Sentinel CRS/grid, save to `data/processed/landsat/<date>.tif` and copy Sentinel to `data/processed/sentinel/<date>.tif`."
    },
