      "ui_instructions": {
        "type": "human_review",
        "prompt": "Is the resampled Landsat image correctly aligned to the Sentinel grid for the example date?"
      },
      "cyclic_routing": {
        "condition": "Is the base-pair alignment correct?",
        "if_true": ["DEV_1_PCA"],
        "if_false": ["ENG_4_ResampleReproject"]
      }
    },
    "DEV_1_PCA": {
      "code": "DEV",
      "category_name": "Model Development",
      "status": "BLOCKED",
      "prerequisites": ["INSP_2_BasePairPreview"],
      "details": "Write `08_compute_pca.py`. Load all preprocessed base-pair stacks from `data/processed/*`. Standardize band values, fit PCA across all base-pair stacks, save PCA model to `models/pca_model.pkl` and per-base-pair PC scores to `data/pca/<date>_pc.npy`."
    },
    "ENG_5_SelectClosestPairs": {
      "code": "ENG",
      "category_name": "Data Engineering",
      "status": "BLOCKED",
      "prerequisites": ["DEV_1_PCA", "ENG_3_BasePairDates"],
      "details": "Write `09_select_similar_pairs.py`. Load PCA model and PC scores for base pairs. For each date in 2023-04-01–2023-11-30 with Sentinel preprocessed data, transform to PC space and compute Euclidean distance to each base-pair. Select two nearest base pairs per date. Save `pair_selection.csv` with columns target_date, base1_date, base2_date."
    },
    "DEV_2_ESTARFM": {
      "code": "DEV",
      "category_name": "Model Development",
      "status": "BLOCKED",
      "prerequisites": ["ENG_5_SelectClosestPairs", "DEV_1_PCA"],
      "details": "Write `10_run_estarfm.py`. For each target_date in `pair_selection.csv`, load corresponding preprocessed Landsat and Sentinel base-pair stacks and Sentinel target image, apply PCA-ESTARFM algorithm to generate synthetic 10 m image, save to `data/synthetic/<target_date>.tif`."
