        "if_false": ["ENG_7_AlignTemporal"]
      }
    },
    "EVAL_1_Correlation": {
      "code": "EVAL",
      "category_name": "Evaluation",
      "status": "BLOCKED",
      "prerequisites": ["INSP_4_AlignReview"],
