    "ENG_8_ExtractRGPFeatures": {
      "code": "ENG",
      "category_name": "Data Engineering",
      "status": "BLOCKED",
      "prerequisites": ["EVAL_1_Correlation"],
      "details": "Write `14_extract_rgp_features.py`. Load `masks/rgp_mask.tif` and `data/indicators.csv`. For each date, compute spatial mean of each indicator over RGP pixels, invert sign for negative means, apply temporal smoothing (TRES) with 3-day window. Save `data/features.csv` with columns Date and smoothed feature1…feature8."
    },
    "INSP_5_FeatureReview": {
      "code": "INSP",
      "category_name": "Manual Inspection",
      "status": "BLOCKED",
      "prerequisites": ["ENG_8_ExtractRGPFeatures"],
      "details": "Plot features from `data/features.csv` against discharge for visual inspection of trends and anomalies.",
      "ui_instructions": {
        "type": "human_review",
        "prompt": "Generate simple line plots of each feature vs discharge. Do the smoothed features reflect expected temporal patterns?"
      },
      "cyclic_routing": {
        "condition": "Are the feature time series acceptable?",
        "if_true": ["DEV_3_TrainModels"],
        "if_false": ["ENG_8_ExtractRGPFeatures"]
      }
