      "category_name": "Evaluation",
      "status": "BLOCKED",
      "prerequisites": ["EXEC_1_Predict2023"],
      "details": "Write `17_evaluate_performance.py`. Load `outputs/predictions.csv`, compute NSE, R², RMSE, MAE for both models. Plot observed vs predicted hydrograph (2023-04-01 to 2023-11-30), save figure `outputs/hydrograph.png` and metrics to `outputs/performance_metrics.json`."
    },
    "DEV_4_UncertaintyMC": {
      "code": "DEV",
