  },
  "INSP_Prototype_Result":{
    "code":"INSP",
    "category_name":"Manual Inspection",
    "status":"BLOCKED",
    "prerequisites":["DEV_Prototype_Kriging"],
    "details":"Human inspects the kriging output GeoTIFFs for plausibility of spatial patterns and resolution.",
    "ui_instructions":{
      "type":"human_review",
      "prompt":"Open `data/kriged_precip_prototype.tif` and `data/kriged_t2m_prototype.tif` in QGIS or Python. Are the interpolated fields reasonable?"
    },
    "cyclic_routing":{
      "condition":"Are the prototype kriging results satisfactory?",
      "if_true":["ACQ_ERA5_Full"],
      "if_false":["DEV_Prototype_Kriging"]
    }
  },
  "ACQ_ERA5_Full":{
    "code":"ACQ",
    "category_name":"Data Acquisition",
    "status":"BLOCKED",
    "prerequisites":["INSP_Prototype_Result"],
    "details":"Write a script named `04_acquire_era5_full.py`. Use `cdsapi` to download ERA5 single-level data for `total_precipitation` and `2m_temperature` for the period 1980–2023 over the shapefile bounding box. Save as a chunked NetCDF or Zarr at `data/era5_1980-2023.nc`."
  },
  "ENG_Full_Preprocessing":{
    "code":"ENG",
    "category_name":"Data Engineering",
    "status":"BLOCKED",
    "prerequisites":["ACQ_ERA5_Full"],
    "details":"Write a script named `05_preprocess_full.py`. Load `data/era5_1980-2023.nc` with xarray and dask, clip to shapefile, reproject to EPSG:3310, chunk time into yearly blocks, and write to `data/era5_full_clipped.zarr`."
  },
  "INSP_Full_Quality":{
    "code":"INSP",
    "category_name":"Manual Inspection",
    "status":"BLOCKED",
    "prerequisites":["ENG_Full_Preprocessing"],
    "details":"Human inspects the Zarr store metadata. Check chunk sizes, variable names, time coverage, and CRS.",
    "ui_instructions":{
      "type":"human_review",
      "prompt":"In Python, open `data/era5_full_clipped.zarr` and inspect `.chunks`, `.coords`, and `.crs`. Confirm they match expectations."
    },
    "cyclic_routing":{
      "condition":"Is the full dataset preprocessing correct?",
      "if_true":["DEV_Kriging_Scripts"],
      "if_false":["ENG_Full_Preprocessing"]
    }
  },
  "DEV_Kriging_Scripts":{
    "code":"DEV",
    "category_name":"Model Development",
    "status":"BLOCKED",
    "prerequisites":["INSP_Full_Quality"],
    "details":"Write a script named `06_prepare_kriging_full.py`. Define a dask-delayed function that takes each yearly time chunk, extracts sample points, fits a variogram automatically, and applies Ordinary Kriging to interpolate both variables to the 1 km grid. Include logic for 10% hold-out cross-validation per chunk."
  },
  "EXEC_Kriging_Full":{
    "code":"EXEC",
    "category_name":"Execution",
    "status":"BLOCKED",
    "prerequisites":["DEV_Kriging_Scripts"],
    "details":"Write a script named `07_execute_kriging_full.py`. Use dask distributed with 24 workers and memory limits to execute the kriging function across all yearly chunks. Save per-year GeoTIFFs to `outputs/kriged/{variable}/{year}.tif`."
  },
  "EVAL_Results":{
    "code":"EVAL",
    "category_name":"Evaluation",
    "status":"BLOCKED",
    "prerequisites":["EXEC_Kriging_Full"],
    "details":"Write a script named `08_evaluate_downscaling.py`. Aggregate kriged outputs back to 31 km grid, compute RMSE and MAE against the original ERA5 values for each year, save metrics to `outputs/metrics.csv`, and generate time-series error plots saved to `outputs/plots/`."
  }
}}

